// План specs/support.md, 1.3 (кейс SUP-03). Два окна admin с разными часовыми поясами. Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { adminPageIn, formatStamp, openTicketDetail, stampMinutes, stamps } from './support-helpers';

test.describe('Поддержка — дата и время сообщений (#3db49a08)', () => {
  test('Message time follows the viewer time zone: New York label is 7 hours earlier than Jerusalem #3db49a08 @desktop @prod-safe', async ({ browser }, testInfo) => {
    // Шаг 1: Jerusalem — метка первого сообщения (после шапки)
    const il = await adminPageIn(browser, testInfo, 'Asia/Jerusalem');
    await openTicketDetail(il);
    const first = stamps(il).nth(1);
    const iso = (await first.getAttribute('datetime'))!;
    expect(iso).toBeTruthy();
    const ilText = (await first.textContent())!.trim();
    expect(ilText).toBe(formatStamp(iso, 'Asia/Jerusalem'));

    // Шаг 2: New York — то же сообщение (по datetime)
    const ny = await adminPageIn(browser, testInfo, 'America/New_York');
    await openTicketDetail(ny);
    const same = ny.locator(`time[datetime="${iso}"]`).first();
    await expect(same).toHaveText(formatStamp(iso, 'America/New_York'));
    const nyText = (await same.textContent())!.trim();

    // Сообщение от 14.10.2026: IDT (UTC+3) − EDT (UTC−4) = 7 ч
    expect(stampMinutes(ilText) - stampMinutes(nyText)).toBe(7 * 60);

    await il.context().close();
    await ny.context().close();
  });
});
